@register_vision_retriever("dummy_vision_retriever")
class DummyVisionRetriever(BaseVisionRetriever):
    """
    Dummy retriever that generates random dense embeddings.
    """

    def __init__(
        self,
        emb_dim_query: int = 16,
        emb_dim_doc: int = 16,
        device: str = "cpu",
        **kwargs,
    ):
        super().__init__(use_visual_embedding=True)
        self.emb_dim_query = emb_dim_query
        self.emb_dim_doc = emb_dim_doc
        self.device = device

    def forward_queries(
        self,
        queries: List[str],
        batch_size: int,
        **kwargs,
    ) -> torch.Tensor:
        return torch.randn(len(queries), self.emb_dim_query)

    def forward_passages(
        self,
        passages: List[Image.Image],
        batch_size: int,
        **kwargs,
    ) -> torch.Tensor:
        return torch.randn(len(passages), self.emb_dim_doc)

    def get_scores(
        self,
        query_embeddings: Union[torch.Tensor, List[torch.Tensor]],
        passage_embeddings: Union[torch.Tensor, List[torch.Tensor]],
        batch_size: Optional[int] = None,
    ) -> torch.Tensor:
        """
        Dot-product similarity between queries and passages.
        """
        if isinstance(query_embeddings, list):
            query_embeddings = torch.stack(query_embeddings)
        if isinstance(passage_embeddings, list):
            passage_embeddings = torch.stack(passage_embeddings)

        scores = torch.einsum("bd,cd->bc", query_embeddings, passage_embeddings)

        return scores

class VisionRetriever(BaseVisionRetriever):
    def __init__(
        self,
        model: torch.nn.Module,
        processor: ProcessorMixin,
    ):
        super().__init__(use_visual_embedding=True)

        self.model = model
        self.model.eval()

        self.processor = processor
        if not hasattr(self.processor, "process_images"):
            raise ValueError("Processor must have `process_images` method")
        if not hasattr(self.processor, "process_queries"):
            raise ValueError("Processor must have `process_queries` method")
        if not hasattr(self.processor, "score"):
            raise ValueError("Processor must have `score` method")

def list_repo_templates(
    repo_id: str,
    *,
    local_files_only: bool,
    revision: Optional[str] = None,
    cache_dir: Optional[str] = None,
) -> list[str]:
    """List template files from a repo.

    A template is a jinja file located under the `additional_chat_templates/` folder.
    If working in offline mode or if internet is down, the method will list jinja template from the local cache - if any.
    """

    if not local_files_only:
        try:
            return [
                entry.path.removeprefix(f"{CHAT_TEMPLATE_DIR}/")
                for entry in list_repo_tree(
                    repo_id=repo_id, revision=revision, path_in_repo=CHAT_TEMPLATE_DIR, recursive=False
                )
                if entry.path.endswith(".jinja")
            ]
        except (GatedRepoError, RepositoryNotFoundError, RevisionNotFoundError):
            raise  # valid errors => do not catch
        except (ConnectionError, HTTPError):
            pass  # offline mode, internet down, etc. => try local files

    # check local files
    try:
        snapshot_dir = snapshot_download(
            repo_id=repo_id, revision=revision, cache_dir=cache_dir, local_files_only=True
        )
    except LocalEntryNotFoundError:  # No local repo means no local files
        return []
    templates_dir = Path(snapshot_dir, CHAT_TEMPLATE_DIR)
    if not templates_dir.is_dir():
        return []
    return [entry.stem for entry in templates_dir.iterdir() if entry.is_file() and entry.name.endswith(".jinja")]

else:
    try:
        for template in list_repo_templates(
            pretrained_model_name_or_path,
            local_files_only=local_files_only,
            revision=revision,
            cache_dir=cache_dir,
        ):
            additional_chat_template_files[template] = f"{CHAT_TEMPLATE_DIR}/{template}.jinja"
    except EntryNotFoundError:
        pass  # No template dir means no template files

else:
    chat_templates = {
        template_name: open(template_file, "r", encoding="utf-8").read()
        for template_name, template_file in resolved_additional_chat_template_files.items()
    }

